from ute_common_abstract_core.network_elem_identification import MsgSourceIdentification
from ute_common_abstract_core.network_elem_identification import CellIdentification
from ute_ue.utils.param_checker import tput_user_value2normalized
from ute_ue.ltecell import LteCell
from ute_ue.exceptions import UeProcedureError, CellRelatedParametersError
from ta_ue_plugin_rtg.rpc.uex_connection import UexConnection
from ta_ue_plugin_rtg.rpc.rpc_call_wraped import RpcCall
import logging


class RtgCell(LteCell):
    """Cell object"""

    def __init__(self, identification):
        """
        Wrap object for easy handling of ute_common_abstract_core.network_elem_identification.CellIdentification.

        :param identification: encapsulated CELL description
        :type: CellIdentification
        """
        self.logger = logging.getLogger('ute_ue.cell')
        uex_conn = UexConnection()
        rpc_conn = uex_conn.rpc_conn
        self.rpc_call = RpcCall(rpc_conn, self.logger).call
        infomodel = identification.get('infomodel', {})
        enb_id = int(infomodel['enb_id'])
        cell_id = int(infomodel['cell_id'])
        params = {'enb_id': enb_id, 'cell_id': cell_id}
        try:
            rpc_response = self.rpc_call(method="get_sector_id", params=params)
            src = rpc_response['src']
            self.sector_id = rpc_response['sector_id']
            if src == "config":
                self.logger.warning("Sector's {} overhead messages cannot be received, sector id fetched from rtg config: enb={} & cell={}".
                                    format(self.sector_id, enb_id, cell_id))
        except UeProcedureError as err:
            raise CellRelatedParametersError(err)

        all_ids = list(identification.items())
        all_ids.append(('rtg', self.sector_id))
        rtg_cell_id = CellIdentification.from_type_id_pairs(identifiers=all_ids, specific_for_tool='rtg')
        super(RtgCell, self).__init__(rtg_cell_id)

        MsgSourceIdentification(identifiers=[('rtg', 'RTG')], network_elem_type='UE', specific_for_tool='rtg')
        # network_elem_type equals 'UE', not 'CELL' to keep only one msg src id

        self.collecting_cell_statistics_started = False

    def start_collecting_cell_statistics(self):
        """
        Start collecting cell statistics
        :return:
        """
        params = {"cell_id": self.sector_id}
        self.rpc_call(method="start_collecting_cell_stats", params=params,
                      log_msg="Cell({0}) - Starting cell stats collection".format(self.sector_id))
        self.collecting_cell_statistics_started = True

    def stop_collecting_cell_statistics(self):
        """
        Stop collecting cell statistics
        :return:
        """
        params = {"cell_id": self.sector_id}
        self.rpc_call(method="stop_collecting_cell_stats", params=params,
                      log_msg="Cell({0}) - Stopping cell stats collection".format(self.sector_id))
        self.collecting_cell_statistics_started = False

    def get_throughput(self, direction, function, type):
        """
        Return cell throughput in bps
        :param direction: "dl" or "ul"
        :param function: one of "maximum", "minimum", "average", "current"
        :param type: one of "data", "signalling", "SRB1"
        :return:
        """
        if not self.collecting_cell_statistics_started:
            raise Exception("Cell statistics collection not started")
        params = {"cell_id": self.sector_id, "dir": direction, "function": self._get_func_shortcut(function), "type": type}
        tput = self.rpc_call(method="get_cell_stats", params=params, log_msg="Cell({0}) - Fetching cell stats".format(self.sector_id))
        self.logger.info('{} {} {} throughput equals {} bps'.format(function.capitalize(), direction.upper(), type, tput))
        return tput

    @staticmethod
    def _get_func_shortcut(function):
        if function not in ["maximum", "minimum", "average", "current"]:
            raise Exception("Wrong current_or_average value")
        return {"maximum": "max", "minimum": "min", "average": "avg", "current": "cur"}[function]

    @staticmethod
    def _verify_type_value(type):
        allowed_values = {"data", "signalling", "SRB1"}
        if type not in allowed_values:
            raise Exception("Wrong type value: {}. Allowed values: {}".format(type, allowed_values))

    def verify_throughput(self, tput_min, tput_max=None, direction="dl", function="current", type="data"):
        """
        :param tput_min:
        :param tput_max:
        :param direction: "dl" or "ul"
        :param function: one of "maximum", "minimum", "average", "current"
        :param type: one of "data", "signalling", "SRB1"
        :return:
        """
        self._verify_type_value(type)
        tput = self.get_throughput(direction, function, type)
        self._verify_throughput(tput / 1000, tput_min, tput_max)

    def _verify_throughput(self, tput, tput_min, tput_max=None):
        normalized_tput_min = tput_user_value2normalized(tput_min)
        if tput < normalized_tput_min:
            msg = 'Expected tput_min={normalized_tput_min} [kbits/s] \n' \
                  'Actual tput={tput} [kbits/sec]'.format(normalized_tput_min=normalized_tput_min,
                                                          tput=tput)
            self.stop_collecting_cell_statistics()
            raise Exception(msg)
        if tput_max and tput > tput_user_value2normalized(tput_max):
            msg = 'Expected tput_min={normalized_tput_min} [kbits/s] \n' \
                  'Expected tput_max={normalized_tput_max} [kbits/s] \n' \
                  'Actual tput={tput} [kbits/sec]'.format(normalized_tput_min=normalized_tput_min,
                                                          normalized_tput_max=tput_user_value2normalized(tput_max),
                                                          tput=tput)
            self.stop_collecting_cell_statistics()
            raise Exception(msg)

    def __del__(self):
        if 'collecting_cell_statistics_started' in dir(self) and self.collecting_cell_statistics_started:
            self.stop_collecting_cell_statistics()
